def stage_proteger_colecao_sintetica(record):
    if not isinstance(record, dict):
        return {"context": None, "decision": "blocked", "effect": "none"}
    if "context" not in record or "sensitive" not in record:
        return {"context": None, "decision": "blocked", "effect": "none"}
    if not isinstance(record["sensitive"], bool):
        return {"context": None, "decision": "blocked", "effect": "none"}
    staged = {"context": record["context"], "decision": "allowed", "effect": "none"}
    if record["sensitive"]:
        staged["decision"] = "blocked"
    return staged

def finalize_proteger_colecao_sintetica(staged):
    return staged
